// Роль new01 («QA П1 0010»): бесплатная, верифицирована, трек «מרחב דתי», ни в одной комнате не состоит.
// Только просмотр (вступление/создание не нажимаются). @data — только из-за одноразового refresh-токена new01.
// Опорные комнаты: «QA-AUTO room 29.10» (латиница, тестовая — не удалять) и «שבת חתן — שאלות ותשובות» (демо).
import { test, expect } from '../../fixtures';
import type { Locator, Page } from '@playwright/test';
import { saveSession } from '../_shared/session';

const LATIN = 'QA-AUTO room 29.10';
const HEBREW = 'שבת חתן — שאלות ותשובות';

async function openRooms(p: Page, width = 390, height = 844) {
  await p.setViewportSize({ width, height });
  await p.goto('/rooms');
  await expect(p.getByText('כל החדרים', { exact: true })).toBeVisible();
  await expect(p.getByRole('button', { name: LATIN, exact: true })).toBeVisible();
}

// Имя обрезано в одну строку с «…» с конца: nowrap + ellipsis + текст шире блока; направление — по языку имени.
async function expectTruncatedAtEnd(name: Locator, dir: 'ltr' | 'rtl') {
  const st = await name.evaluate((e) => {
    const s = getComputedStyle(e);
    return { sw: e.scrollWidth, cw: e.clientWidth, to: s.textOverflow, ws: s.whiteSpace, dir: s.direction };
  });
  expect(st.to, 'text-overflow').toBe('ellipsis');
  expect(st.ws, 'одна строка').toBe('nowrap');
  expect(st.sw, 'имя длиннее места → обрезано').toBeGreaterThan(st.cw);
  expect(st.dir, `направление текста имени (${dir} → «…» в конце строки)`).toBe(dir);
}

test.describe('Библиотека комнат (/rooms) — new01', () => {
  test.describe.configure({ timeout: 120_000 });

  test('Шапка «כל החדרים» с «→»/«+»/поиском, чип «הכול», список: имя, «מתמשך/זמני», тема, «להצטרף»; «מפה» и навбар @iphone @data (#c32a98)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      await openRooms(p);
      // Шапка (Р2): «חזרה» (→), «פתיחת חדר» (+), поиск, трек.
      await expect(p.getByRole('button', { name: 'חזרה' })).toBeVisible();
      await expect(p.getByRole('button', { name: 'פתיחת חדר' })).toBeVisible();
      await expect(p.getByRole('textbox', { name: 'חיפוש חדרים' })).toBeVisible();
      // Чип «הכול» первым справа (Р3).
      const all = p.getByRole('radio', { name: 'הכול', exact: true });
      await expect(all).toBeVisible();
      const chipX = await p.getByRole('radio').evaluateAll((els) => els.map((e) => e.getBoundingClientRect().right));
      const allBox = (await all.boundingBox())!;
      expect(Math.abs(Math.max(...chipX) - (allBox.x + allBox.width)), '«הכול» — крайний правый чип').toBeLessThanOrEqual(1);
      // Строки (AC 3): имя, длительность, тема; у не-участника — «להצטרף» (Р4).
      for (const [name, theme] of [[LATIN, 'בילויים'], [HEBREW, 'קהילה']] as const) {
        const row = p.getByRole('button', { name, exact: true });
        await expect(row.getByText(/^(מתמשך|זמני)$/)).toBeVisible();
        await expect(row.getByText(theme, { exact: true })).toBeVisible();
      }
      const rows = await p.getByRole('button', { name: /./ }).filter({ has: p.getByText(/^(מתמשך|זמני)$/) }).count();
      await expect(p.getByRole('button', { name: 'להצטרף', exact: true })).toHaveCount(rows);
      // Кнопка «מפה» (Р3) и нижняя навигация (Р2).
      await expect(p.getByRole('button', { name: 'מפה' })).toBeVisible();
      for (const tab of ['חדרים', 'מיקום', 'לייקים', 'הודעות']) await expect(p.getByRole('tab', { name: tab })).toBeVisible();
    } finally {
      await saveSession(p, 'new01');
    }
  });

  test('Длинные имена комнат режутся «…» с конца — латиница и иврит, 390 и 375; то же в карусели «חדרים» на /social @iphone @data (#c32a98)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      for (const width of [390, 375]) {
        await openRooms(p, width, width === 390 ? 844 : 667);
        const row = (n: string) => p.getByRole('button', { name: n, exact: true }).getByText(n, { exact: true });
        await expectTruncatedAtEnd(row(LATIN), 'ltr');
        await expectTruncatedAtEnd(row(HEBREW), 'rtl');
      }
      // Карусель комнат на /social (Р5).
      await p.setViewportSize({ width: 390, height: 844 });
      await p.goto('/social');
      const card = p.getByRole('button', { name: LATIN, exact: true }).getByText(LATIN, { exact: true });
      await expect(card).toBeVisible();
      const st = await card.evaluate((e) => ({ sw: e.scrollWidth, cw: e.clientWidth, to: getComputedStyle(e).textOverflow, dir: getComputedStyle(e).direction }));
      if (st.sw > st.cw) {
        expect(st.to, 'в карусели обрезка «…»').toBe('ellipsis');
        expect(st.dir, 'латиница — «…» в конце').toBe('ltr');
      }
    } finally {
      await saveSession(p, 'new01');
    }
  });

  test('«+» у бесплатной — окно Premium «רוצה לפתוח חדר משלך?», «לא עכשיו» закрывает @iphone @data (#c32a98)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      await openRooms(p);
      await p.getByRole('button', { name: 'פתיחת חדר' }).click();
      // AC 7: не-Premium → апгрейд (создание не открывается).
      const sheet = p.getByRole('dialog');
      await expect(sheet.getByText('רוצה לפתוח חדר משלך?')).toBeVisible();
      await expect(sheet.getByRole('button', { name: 'לשדרג ל-Premium' })).toBeVisible();
      expect(p.url()).not.toContain('/rooms/new');
      await sheet.getByRole('button', { name: 'לא עכשיו' }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      await expect(p).toHaveURL(/\/rooms$/);
    } finally {
      await saveSession(p, 'new01');
    }
  });

  test('Тап по комнате — экран комнаты: имя, тема, участники; не-участнику «להצטרף לחדר»; «מפה» → /map @iphone @data (#c32a98)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      await openRooms(p);
      await p.getByRole('button', { name: LATIN, exact: true }).click();
      await p.waitForURL(/\/rooms\/[0-9a-f-]{36}$/);
      // AC: переход в комнату; не-участник видит приглашение вступить (не нажимаем).
      await expect(p.getByRole('button', { name: 'פרטי החדר' }).first()).toContainText(LATIN);
      await expect(p.getByRole('button', { name: 'פרטי החדר' }).first()).toContainText(/משתתפים/);
      await expect(p.getByText('הצטרפו לחדר כדי לראות את השיחה ולכתוב')).toBeVisible();
      await expect(p.getByRole('button', { name: 'להצטרף לחדר' })).toBeVisible();
      // Назад → библиотека, «מפה» → карта (Р3).
      await p.getByRole('button', { name: 'חזרה' }).click();
      await expect(p.getByText('כל החדרים', { exact: true })).toBeVisible();
      await p.getByRole('button', { name: 'מפה' }).click();
      await p.waitForURL(/\/map/);
    } finally {
      await saveSession(p, 'new01');
    }
  });
});
